export const colorFields=['color','backgroundColor','borderColor','fill','stroke'];
export const validColor=value=>typeof value==='string'&&value.length<=160&&/^(?:#[\da-f]{3}(?:[\da-f]{1}|[\da-f]{3}|[\da-f]{5})?|transparent|currentColor|black|white|(?:rgb|rgba|hsl|hsla|oklch|oklab|lab|lch)\([\d.%+\-/,\s]+\)|var\(--[\w-]+(?:,\s*#[\da-f]{3}(?:[\da-f]{1}|[\da-f]{3}|[\da-f]{5})?)?\))$/i.test(value);
export const fields={width:[0,3000],height:[0,2000],padding:[0,200],gap:[0,200],borderRadius:[0,200],fontSize:[8,120],lineHeight:[8,200],letterSpacing:[-10,30],top:[-3000,3000],right:[-3000,3000],bottom:[-3000,3000],left:[-3000,3000]};
export const layoutValues={display:['block','flex','inline-flex','grid'],flexDirection:['row','column','row-reverse','column-reverse'],justifyContent:['flex-start','center','flex-end','space-between','space-around','space-evenly'],alignItems:['stretch','flex-start','center','flex-end','baseline'],flexWrap:['nowrap','wrap','wrap-reverse'],position:['static','relative','absolute'],flexGrow:['0','1'],flexShrink:['0','1'],alignSelf:['auto','stretch','flex-start','center','flex-end'],width:['auto','max-content','100%'],height:['auto','max-content','100%']};
export function validChange(c){if(!c||!/^[A-Za-z0-9_-]{1,100}$/.test(c.id)||!['desktop','mobile'].includes(c.viewport))return false;if(c.unit===''&&layoutValues[c.property]?.includes(c.value))return true;if(['top','right','bottom','left'].includes(c.property)&&c.unit===''&&c.value==='auto')return true;if(colorFields.includes(c.property))return c.unit===''&&validColor(c.value);return Object.hasOwn(fields,c.property)&&typeof c.value==='number'&&Number.isFinite(c.value)&&c.value>=fields[c.property][0]&&c.value<=fields[c.property][1]&&(c.unit==='px'||(['width','height'].includes(c.property)&&c.unit==='%'&&c.value<=100));}
export function validateBundle(b){if(b?.schema!=='dragger/v1'||!Array.isArray(b.changes)||b.changes.length>500||!b.changes.every(validChange))throw Error('올바르지 않은 Dragger 변경 파일입니다.');return {schema:'dragger/v1',changes:b.changes.map(({id,property,value,unit,viewport})=>({id,property,value,unit,viewport}))};}
export function css(b){const data=validateBundle(b);return '/* Generated by Dragger. Load after product styles. */\n'+data.changes.map(c=>{const rule=`[data-dragger-id="${c.id}"] { ${c.property.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}: ${c.value}${c.unit} !important; }`;return `@media (${c.viewport==='mobile'?'max-width: 767px':'min-width: 768px'}) { ${rule} }`;}).join('\n')+'\n';}
export function serviceURL(value){const u=new URL(value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('http 또는 https 주소를 입력하세요.');return u.href;}
